1	/* ============================================================
2	   PORTFOLIO CAROUSEL — portfolio-carousel.module.css
3	   Extracted verbatim from boldteq-v1-0.webflow.css
4	   ============================================================ */
5	
6	/* Carousel outer column — center-aligned */
7	.column-4x-large-centered {
8	  align-items: center;
9	}
10	
11	/* Slider relative wrapper */
12	.sliderRelative {
13	  position: relative;
14	  width: 100%;
15	}
16	
17	.section-regular-2 {
18	  background-color: #fff;
19	  padding: 64px 15% 64px 2%;
20	  position: relative;
21	  overflow: hidden;
22	}
23	
24	.img-slider-sec {
25	  padding-top: 20px;
26	  padding-right: 0%;
27	}
28	
29	.column-4x-large {
30	  grid-column-gap: 80px;
31	  grid-row-gap: 80px;
32	  flex-flow: column;
33	  display: flex;
34	}
35	
36	/* Slider wrapper */
37	.gallery-13-slider {
38	  background-color: #0000;
39	  height: auto;
40	  padding-bottom: 0;
41	  position: relative;
42	  width: 100%;
43	}
44	
45	/* Mask — overflow visible matches Webflow's .w-slider-mask override */
46	.gallery-13-mask {
47	  max-width: none;
48	  height: auto;
49	  overflow: visible;
50	}
51	
52	/* Slider track — replaces inline style.
53	   Webflow uses margin-right: 24px on each slide, not CSS gap. */
54	.gallery-13-track {
55	  display: flex;
56	  height: auto;
57	}
58	
59	.gallery-13-slide {
60	  max-width: calc(25% - 12px);
61	  height: 100%;
62	  margin-right: 24px;
63	  flex-shrink: 0;
64	}
65	
66	/* Cards */
67	.gallery-13-card {
68	  aspect-ratio: 1 / 1.25;
69	  border: 1px solid #000;
70	  border-radius: 20px;
71	  width: 100%;
72	  min-height: 392px;
73	  padding: 10px;
74	  position: relative;
75	  overflow: hidden;
76	}
77	
78	.cream {
79	  aspect-ratio: 1 / 1.22;
80	  background-color: #fbf2e4;
81	  border-style: none;
82	  min-height: auto;
83	  padding: 10px;
84	}
85	
86	.light-green {
87	  aspect-ratio: 1 / 1.22;
88	  background-color: #e6fccd;
89	  border-style: none;
90	  min-height: auto;
91	  padding: 10px;
92	}
93	
94	.light-purple {
95	  aspect-ratio: 1 / 1.22;
96	  background-color: #4da1af1a;
97	  border-style: none;
98	  min-height: auto;
99	  padding: 10px;
100	}
101	
102	.light-orange {
103	  aspect-ratio: 1 / 1.22;
104	  background-color: #ff8a8a14;
105	  border-style: none;
106	  min-height: auto;
107	  padding: 10px;
108	}
109	
110	/* Image outer wrapper — Webflow base: no height/max-height, padding only */
111	.gallery-image-outer {
112	  border-radius: 15px;
113	  margin-bottom: 20px;
114	  padding-top: 20px;
115	  padding-left: 20px;
116	  padding-right: 20px;
117	}
118	
119	.green {
120	  background-color: #0d4a4c;
121	  min-height: auto;
122	}
123	
124	.green-light {
125	  background-color: #abf330;
126	  height: auto;
127	  min-height: auto;
128	}
129	
130	.orange-light {
131	  background-color: #ffc671;
132	  min-height: auto;
133	}
134	
135	.olive-green {
136	  background-color: #5e6350;
137	  min-height: auto;
138	}
139	
140	/* The portfolio image — Webflow base: max-height 357px, height auto */
141	.image-cover {
142	  object-fit: cover;
143	  object-position: 50% 0%;
144	  border-radius: 10px;
145	  width: 100%;
146	  height: auto;
147	  min-height: auto;
148	  max-height: 357px;
149	  display: block;
150	  position: relative;
151	  overflow: hidden;
152	}
153	
154	.radius-0 {
155	  border-radius: 0;
156	}
157	
158	/* Caption */
159	.gallery-13-caption {
160	  text-align: left;
161	  background-color: #0000;
162	  border-radius: 8px;
163	  height: auto;
164	  padding: 0;
165	  position: relative;
166	  inset: auto;
167	  overflow: visible;
168	}
169	
170	.heading-3 {
171	  color: #082753;
172	  text-align: left;
173	  font-family: 'Roobert PRO', Arial, sans-serif;
174	  font-size: 25px;
175	  font-weight: 700;
176	}
177	
178	/* Color variants for heading-3 */
179	.heading-3-green,
180	.heading-3-green-light,
181	.heading-3-purple {
182	  color: #020e41;
183	  text-align: center;
184	  font-size: 1.3rem;
185	}
186	
187	.heading-3-orange {
188	  color: #111c19;
189	  text-align: center;
190	  -webkit-text-stroke-color: #ff8a8a;
191	  font-size: 1.3rem;
192	}
193	
194	/* Nav buttons */
195	.gallery-13-button {
196	  width: auto;
197	  position: absolute;
198	  inset: auto 0% 0% auto;
199	  top: 50%;
200	  transform: translateY(-50%);
201	  z-index: 10;
202	  background: none;
203	  border: none;
204	  padding: 0;
205	  cursor: pointer;
206	}
207	
208	.button-left {
209	  left: -1.5%;
210	  right: auto;
211	}
212	
213	.button-right {
214	  right: 0.5%;
215	}
216	
217	.icon-button-outline-large {
218	  color: #000;
219	  background-color: #fff;
220	  border: 1px solid #c9d2d9;
221	  border-radius: 11px;
222	  flex: none;
223	  justify-content: center;
224	  align-items: center;
225	  width: 48px;
226	  height: 48px;
227	  display: flex;
228	  cursor: pointer;
229	}
230	
231	.icon-regular {
232	  width: 24px;
233	  height: 24px;
234	  flex: none;
235	  justify-content: center;
236	  align-items: center;
237	  display: flex;
238	}
239	
240	.icon-blue {
241	  color: #21cfff;
242	}
243	
244	.container-large-2 {
245	  z-index: 1;
246	  width: 100%;
247	  max-width: 1280px;
248	  margin-left: auto;
249	  margin-right: auto;
250	  position: relative;
251	}
252	
253	/* Dot navigation — matches .w-slider-nav + .w-slider-dot from index.html inline style */
254	.slider-dots {
255	  justify-content: flex-start;
256	  align-items: center;
257	  max-width: calc(100% - 112px);
258	  margin-left: 0;
259	  padding-top: 16px;
260	  padding-bottom: 16px;
261	  display: flex;
262	  gap: 4px;
263	}
264	
265	.slider-dot {
266	  /* Visual 12×12 via width/height; hit area expanded to 24×24 via padding
267	     for WCAG 2.5.8 tap-target compliance. background-clip: content-box keeps
268	     the colored circle at 12×12 — padding area is transparent/invisible. */
269	  height: 12px;
270	  width: 12px;
271	  border-radius: 50%;
272	  border: none;
273	  cursor: pointer;
274	  transition: background-color 0.2s;
275	  background-color: #EDF0F2;
276	  background-clip: content-box;
277	  margin-bottom: 0;
278	  padding: 6px;
279	  box-sizing: content-box;
280	  flex-shrink: 0;
281	}
282	
283	.slider-dot-active {
284	  background-color: #000;
285	}
286	
287	/* ============================================================
288	   min-width: 1280px
289	   ============================================================ */
290	@media screen and (min-width: 1280px) {
291	  .section-regular-2.img-slider-sec {
292	    padding-right: 0%;
293	  }
294	
295	  .gallery-13-button.button-right {
296	    right: 0.5%;
297	  }
298	
299	  /* image-cover.radius-0 keeps height: auto */
300	  .image-cover {
301	    height: 360px;
302	  }
303	
304	  .image-cover.radius-0 {
305	    height: auto;
306	  }
307	
308	  .gallery-13-slide {
309	    min-height: 392px;
310	  }
311	
312	  .gallery-13-mask {
313	    height: auto;
314	  }
315	
316	  .gallery-13-card.cream,
317	  .gallery-13-card.light-green,
318	  .gallery-13-card.light-purple,
319	  .gallery-13-card.light-orange {
320	    aspect-ratio: 1 / 1.2;
321	  }
322	
323	  /* Webflow has no max-height on .gallery-image-outer at 1280px */
324	}
325	
326	/* ============================================================
327	   min-width: 1440px
328	   ============================================================ */
329	@media screen and (min-width: 1440px) {
330	  .section-regular-2 {
331	    max-width: none;
332	    padding-right: 22%;
333	  }
334	
335	  .section-regular-2.img-slider-sec {
336	    max-width: none;
337	    padding-right: 0%;
338	  }
339	
340	  .gallery-13-button.button-right {
341	    right: 0.5%;
342	  }
343	
344	  .image-cover {
345	    object-fit: cover;
346	    height: 410px;
347	    min-height: auto;
348	    max-height: 420px;
349	    position: static;
350	  }
351	
352	  .image-cover.radius-0 {
353	    height: auto;
354	  }
355	
356	  .gallery-13-slider {
357	    align-self: auto;
358	    max-width: none;
359	  }
360	
361	  .gallery-13-slide {
362	    height: 100%;
363	    min-height: 392px;
364	    position: static;
365	  }
366	
367	  .gallery-13-mask {
368	    height: auto;
369	  }
370	
371	  .gallery-13-card.cream,
372	  .gallery-13-card.light-green,
373	  .gallery-13-card.light-purple,
374	  .gallery-13-card.light-orange {
375	    aspect-ratio: auto;
376	  }
377	
378	  /* Webflow has no max-height on .gallery-image-outer at 1440px */
379	}
380	
381	/* ============================================================
382	   max-width: 991px
383	   ============================================================ */
384	@media screen and (max-width: 991px) {
385	  .section-regular-2.img-slider-sec {
386	    padding-right: 2%;
387	  }
388	
389	  .gallery-13-button.button-left {
390	    left: -1%;
391	  }
392	
393	  .gallery-13-button.button-right {
394	    right: -1%;
395	  }
396	
397	  .column-4x-large {
398	    grid-column-gap: 64px;
399	    grid-row-gap: 64px;
400	  }
401	
402	  .gallery-13-slide {
403	    max-width: calc(50% - 12px);
404	  }
405	
406	  .gallery-13-mask {
407	    max-width: none;
408	    height: auto;
409	  }
410	
411	  .gallery-13-card.cream,
412	  .gallery-13-card.light-green,
413	  .gallery-13-card.light-purple,
414	  .gallery-13-card.light-orange {
415	    aspect-ratio: auto;
416	  }
417	
418	  /* Webflow has no max-height on .gallery-image-outer at 991px */
419	}
420	
421	/* ============================================================
422	   max-width: 767px
423	   ============================================================ */
424	@media screen and (max-width: 767px) {
425	  .column-4x-large {
426	    grid-column-gap: 40px;
427	    grid-row-gap: 40px;
428	  }
429	
430	  .gallery-13-slide {
431	    max-width: calc(50% - 12px);
432	  }
433	
434	  .gallery-13-mask {
435	    max-width: none;
436	    height: auto;
437	  }
438	}
439	
440	/* Webflow has no max-height on .gallery-image-outer at 767px */
441	
442	/* ============================================================
443	   max-width: 479px  (mobile)
444	   ============================================================ */
445	@media screen and (max-width: 479px) {
446	  .section-regular-2 {
447	    padding-top: 60px;
448	    padding-bottom: 60px;
449	    padding-left: 4%;
450	  }
451	
452	  .section-regular-2.img-slider-sec {
453	    padding-top: 40px;
454	    padding-bottom: 50px;
455	  }
456	
457	  .gallery-13-button.button-left {
458	    left: -2.5%;
459	  }
460	
461	  .gallery-13-slide {
462	    max-width: calc(100% - 12px);
463	    height: 100%;
464	    margin-right: 15px;
465	  }
466	
467	  .gallery-13-mask {
468	    max-width: none;
469	    height: auto;
470	  }
471	
472	  .heading-3 {
473	    font-size: 22px;
474	    line-height: 26px;
475	  }
476	
477	  /* Webflow has no max-height on .gallery-image-outer at 479px */
478	}
