1	/* Badge pill text */
2	.badgePillText {
3	  margin: 0;
4	  font-size: 12px;
5	  line-height: 32px;
6	}
7	
8	/* ==========================================================
9	   works-sec  (Webflow: .works-sec)
10	   ========================================================== */
11	.worksSec {
12	  background-color: transparent;
13	  padding: 20px 5% 60px;
14	  position: relative;
15	}
16	
17	/* ==========================================================
18	   Container  (Webflow: .container-large-3)
19	   ========================================================== */
20	.containerLarge3 {
21	  width: 100%;
22	  max-width: 1280px;
23	  margin-left: auto;
24	  margin-right: auto;
25	}
26	
27	/* ==========================================================
28	   Badge row  (Webflow: .benefit-subhead-out / .benefitsubott)
29	   ========================================================== */
30	.benefitSubheadOut {
31	  grid-column-gap: 10px;
32	  grid-row-gap: 10px;
33	  justify-content: center;
34	  align-items: center;
35	  display: flex;
36	}
37	
38	.benefitsubott {
39	  background-color: #21cfff12;
40	  border: 1px solid #05bafe;
41	  border-radius: 20px;
42	  margin-bottom: 0;
43	  padding: 0 13px;
44	  line-height: 14px;
45	}
46	
47	/* ==========================================================
48	   Gradient text  (Webflow: .faq-sky-text)
49	   ========================================================== */
50	.faqSkyText {
51	  color: #21cfff;
52	  text-transform: capitalize;
53	  -webkit-text-fill-color: transparent;
54	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
55	  -webkit-background-clip: text;
56	  background-clip: text;
57	  font-weight: 500;
58	}
59	
60	/* ==========================================================
61	   Section heading  (Webflow: .heading-2.margin-bottom-24px)
62	   ========================================================== */
63	.heading2 {
64	  color: #082753;
65	  font-family: Roobert PRO, Arial, sans-serif;
66	  font-size: 40px;
67	  text-align: center;
68	  line-height: 45px;
69	  margin-bottom: 20px;
70	}
71	
72	/* ==========================================================
73	   Body copy  (Webflow: .paragraph.center)
74	   ========================================================== */
75	.paragraph {
76	  color: #2b2b2b;
77	  font-size: 16px;
78	  line-height: 28px;
79	  text-align: center;
80	  margin-bottom: 0;
81	}
82	
83	/* ==========================================================
84	   Grid  (Webflow: .feature-grid.margin-top-40px.hiring-slider)
85	   Webflow uses Slick with slidesToShow: 3 at desktop — only 3 cards
86	   visible at a time (1 row), paginating via dots. We replicate with
87	   CSS horizontal scroll-snap so all 6 cards stay in the DOM but only
88	   3 are visible at once, matching the Webflow section height.
89	   ========================================================== */
90	.featureGrid {
91	  display: flex;
92	  flex-direction: row;
93	  overflow-x: auto;
94	  scroll-snap-type: x mandatory;
95	  -webkit-overflow-scrolling: touch;
96	  gap: 20px;
97	  margin-top: 40px;
98	  scrollbar-width: none;
99	}
100	
101	.featureGrid::-webkit-scrollbar {
102	  display: none;
103	}
104	
105	/* ==========================================================
106	   Card  (Webflow: .feature-card.space-between)
107	   At desktop: flex child sized to 1/3 of container (minus gaps)
108	   so exactly 3 cards are visible at once, matching Slick slidesToShow:3
109	   ========================================================== */
110	.featureCard {
111	  grid-column-gap: 0px;
112	  grid-row-gap: 0px;
113	  text-align: center;
114	  mix-blend-mode: normal;
115	  background-color: #def4ff;
116	  background-image: none;
117	  border: 1px solid #009ce0;
118	  border-radius: 20px;
119	  flex-flow: column;
120	  justify-content: space-between;
121	  align-items: center;
122	  padding: 25px 17px 17px;
123	  text-decoration: none;
124	  display: flex;
125	  /* Desktop: show 3 cards at once (gap: 20px × 2 = 40px total) */
126	  flex: 0 0 calc(33.333% - 14px);
127	  min-width: calc(33.333% - 14px);
128	  scroll-snap-align: start;
129	}
130	
131	.featureCard:hover {
132	  background-color: #cdebfa;
133	  border-color: #009ce0;
134	}
135	
136	/* ==========================================================
137	   Text wrapper  (Webflow: .text-wrapper)
138	   ========================================================== */
139	.textWrapper {
140	  margin-bottom: 20px;
141	}
142	
143	/* ==========================================================
144	   Card title  (Webflow: .subheading-large)
145	   ========================================================== */
146	.subheadingLarge {
147	  color: #082753;
148	  letter-spacing: -0.02em;
149	  margin-bottom: 10px;
150	  font-family: Roobert PRO, Arial, sans-serif;
151	  font-size: 20px;
152	  font-weight: 700;
153	  line-height: 25px;
154	}
155	
156	/* ==========================================================
157	   Card body copy  (Webflow: .paragraph-small-2.margin-bottom-20px.grid-wrap)
158	   ========================================================== */
159	.paragraphSmall2 {
160	  color: #2b2b2b;
161	  min-height: auto;
162	  font-family: Roobert PRO, Arial, sans-serif;
163	  font-size: 16px;
164	  letter-spacing: -0.08px;
165	  margin-bottom: 0;
166	  line-height: 28px;
167	  max-width: 315px;
168	}
169	
170	/* ==========================================================
171	   Card image  (Webflow: .full-width-image.drop-shadow.blue-shadow)
172	   ========================================================== */
173	.fullWidthImage {
174	  display: block;
175	  width: 100%;
176	  height: auto;
177	  filter: drop-shadow(0px 0px 30px rgba(0, 126, 188, 0.1));
178	}
179	
180	/* ==========================================================
181	   Dots navigation (replaces Slick dots)
182	   Webflow Slick dots: display flex, center, gap 10px, margin-top 50px
183	   ========================================================== */
184	.sliderDots {
185	  display: flex;
186	  justify-content: center;
187	  gap: 10px;
188	  list-style: none;
189	  margin: 50px 0 0;
190	  padding: 0;
191	}
192	
193	.sliderDot {
194	  background: transparent;
195	  border: 1px solid #d1d1d1;
196	  border-radius: 20px;
197	  width: 12px;
198	  height: 12px;
199	  padding: 0;
200	  cursor: pointer;
201	  transition: background-image 0.2s ease;
202	}
203	
204	.sliderDot.active {
205	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
206	  border-color: transparent;
207	}
208	
209	/* ==========================================================
210	   @media (min-width: 1280px)
211	   Webflow line 21922: .feature-card → bg/border (unchanged)
212	   Webflow line 21927: .feature-card.space-between → pl/pr 20px
213	   Webflow line 21944: .subheading-large → 25px / 32px
214	   Webflow line 21932: .container-large-3 → max-width 1280px
215	   ========================================================== */
216	@media screen and (min-width: 1280px) {
217	  .featureCard {
218	    background-color: #def4ff;
219	    border-color: #009ce0;
220	    padding-left: 20px;
221	    padding-right: 20px;
222	  }
223	
224	  .containerLarge3 {
225	    max-width: 1280px;
226	  }
227	
228	  .paragraphSmall2 {
229	    max-width: 308px;
230	  }
231	
232	  .subheadingLarge {
233	    font-size: 25px;
234	    line-height: 32px;
235	  }
236	}
237	
238	/* ==========================================================
239	   @media (min-width: 1440px)
240	   Webflow line 23357 — .feature-card.space-between gets pl/pr 25px
241	   container-large-3 gets max-width: 1320px
242	   ========================================================== */
243	@media screen and (min-width: 1440px) {
244	  .featureCard {
245	    background-color: #def4ff;
246	    background-image: none;
247	    border-color: #009ce0;
248	    justify-content: space-between;
249	    align-items: center;
250	    padding-left: 25px;
251	    padding-right: 25px;
252	  }
253	
254	  .containerLarge3 {
255	    max-width: 1320px;
256	  }
257	
258	  .paragraphSmall2 {
259	    max-width: 308px;
260	    margin-left: auto;
261	    margin-right: auto;
262	  }
263	}
264	
265	/* ==========================================================
266	   @media (max-width: 991px)
267	   Webflow: Slick breakpoint 980px → slidesToShow: 2. We show 2 cards
268	   at once in the horizontal scroll carousel.
269	   ========================================================== */
270	@media screen and (max-width: 991px) {
271	  .featureCard {
272	    /* Show 2 cards at once at tablet (Slick slidesToShow: 2 at <980px) */
273	    flex: 0 0 calc(50% - 10px);
274	    min-width: calc(50% - 10px);
275	  }
276	
277	  .paragraphSmall2 {
278	    max-width: none;
279	  }
280	
281	  .heading2 {
282	    font-size: 35px;
283	    line-height: 45px;
284	  }
285	}
286	
287	/* ==========================================================
288	   @media (max-width: 767px)
289	   Webflow line 27051: .feature-grid.margin-top-40px → 1 col (plain grid)
290	   Webflow line 27055: .feature-grid.margin-top-40px.hiring-slider → 20px gap
291	     (Slick still controls layout here — still shows 2 at breakpoint 980)
292	   Webflow line 27177: .works-sec → padding-top: 0; padding-bottom: 50px
293	   ========================================================== */
294	@media screen and (max-width: 767px) {
295	  .worksSec {
